func (m *UserMutation) ResetEdge(name string) error {
	switch name {
	case user.EdgeDevices:
		m.ResetDevices()
		return nil
	case user.EdgeConversations:
		m.ResetConversations()
		return nil
	case user.EdgeMemories:
		m.ResetMemories()
		return nil
	case user.EdgeTodos:
		m.ResetTodos()
		return nil
	case user.EdgeActionItems:
		m.ResetActionItems()
		return nil
	case user.EdgeChatMessages:
		m.ResetChatMessages()
		return nil
	case user.EdgeChatSessions:
		m.ResetChatSessions()
		return nil
	case user.EdgeNotificationTokens:
		m.ResetNotificationTokens()
		return nil
	case user.EdgeFolders:
		m.ResetFolders()
		return nil
	case user.EdgeGoals:
		m.ResetGoals()
		return nil
	case user.EdgeCalendarMeetings:
		m.ResetCalendarMeetings()
		return nil
	case user.EdgeCsatRatings:
		m.ResetCsatRatings()
		return nil
	case user.EdgeChatFiles:
		m.ResetChatFiles()
		return nil
	}
	return fmt.Errorf("unknown User edge %s", name)
}
